/**
 * How Single key with cords in a circle (`maru-ni-hitotsu-kagi`) is constructed, in a line in each language: the text a crest's card shows beside its steps.
 * It is here, not on the crest's record, so that the manifest stays small; `crestConstruction()` loads it.
 *
 * @example
 * ```ts no-run
 * import { description } from "@johnmorrisdotca/kamon-crests/steps/maru-ni-hitotsu-kagi";
 *
 * console.log(description.en.length > 30, description.ja.endsWith("。")); // true true
 * ```
 */
const description: { en: string; ja: string } = {"en":"Rule the key from its rounded shaft into a rectangular spiral. Leave a small eye at the foot of the shaft. Loop the cords below the head and to each side, with a tassel at each outer end. Strike the enclosing ring.","ja":"丸い軸の先から、角を曲がりながら内へ巻く鍵を引きます。軸の下に小さな穴をあけます。鍵の頭の下と軸の両側に紐を巻き、二つの端に房を付け、外に輪を打ちます。"};

export default construction;
export { construction, description };
